// The shell. Owner: foundation (shared). It mounts the three areas and owns only the top bar,
// the page layout and the theme switch. Area files: runbook/ (A), entry/ (B), review/ (C).
// Builders fill the slots their area exports; they do not edit this file.
import "./theme.css";
import "./shell.css";
import { CircleHalfIcon, IconContext, LockSimpleIcon, MoonIcon, SunIcon, WarningIcon } from "@phosphor-icons/react";
import { useEffect, useRef, useState } from "react";
import { createRoot } from "react-dom/client";
import { Button, Tooltip, TooltipProvider } from "./primitives";
import { EntryEmpty, EntryOverlays, EntryTopbar, OutcomeHeader, SourcesRail } from "./entry";
import { ActivityLog, ApprovalLayer, ReviewDock } from "./review";
import { RunbookDocument } from "./runbook";
import { applyRecipe, recipeFromHash } from "./recipe";
import { MosaicProvider, useMosaic } from "./state";

function App() {
  return (
    <MosaicProvider>
      <IconContext.Provider value={{ weight: "bold", size: 18 }}>
        <TooltipProvider>
          <div className="app">
            <TopBar />
            <div className="layout">
              <SourcesRail />
              <RunbookDocument
                header={<OutcomeHeader />}
                empty={<EntryEmpty />}
                footer={<ActivityLog />}
              />
            </div>
            <ReviewDock />
            <ApprovalLayer />
            <EntryOverlays />
            <RecipeLoader />
          </div>
        </TooltipProvider>
      </IconContext.Provider>
    </MosaicProvider>
  );
}

/** Opening a recipe link rebuilds its workspace once this Mosaic's config has loaded. */
function RecipeLoader() {
  const { state, actions } = useMosaic();
  const started = useRef(false);
  useEffect(() => {
    if (started.current || !state.host) return;
    const recipe = recipeFromHash();
    if (!recipe) return;
    started.current = true;
    history.replaceState(null, "", location.pathname);
    void applyRecipe(recipe, actions, state.host.agent);
  }, [state.host, actions]);
  return null;
}

function TopBar() {
  const { state } = useMosaic();
  return (
    <header className="topbar">
      <div className="brand">
        <MosaicMark complete={state.conns.length > 0} />
        <span>Mosaic</span>
      </div>
      <nav className="crumbs" aria-label="Location">
        <span className="dim">Runbooks</span>
        <span className="sep">/</span>
        <span className="crumb-title">{state.title.trim() || "Untitled"}</span>
      </nav>
      <div className="top-right">
        <EntryTopbar />
        <ThemeSwitch />
        <BuildMark />
      </div>
    </header>
  );
}

/**
 * Mosaic's own source fingerprint, checked again after every connection. Quiet until a check has
 * run: then "Mosaic unchanged" (connecting a site added steps, not code), or a warning if it moved.
 */
function BuildMark() {
  const { state } = useMosaic();
  if (!state.host) return null;
  const build = state.host.build;
  const check = state.buildCheck;
  const tip =
    check === "same"
      ? `Mosaic's source fingerprint is still ${build}, the same as when this page loaded. Connecting a site added steps without changing Mosaic's code.`
      : check === "changed"
        ? `Mosaic's source fingerprint no longer matches ${build}, the one this page loaded. Reload before you approve anything.`
        : `Mosaic's source fingerprint is ${build}. It is checked again each time you connect a site.`;
  return (
    <Tooltip content={tip} side="bottom">
      <Button variant="tertiary" size="sm" className={`build ${check ?? ""}`} icon={check === "changed" ? <WarningIcon /> : <LockSimpleIcon />} aria-label={`${check === "same" ? "Mosaic unchanged" : check === "changed" ? "Mosaic changed" : "Mosaic's source fingerprint"}. ${tip}`}>
        {check && <span className="build-label">{check === "same" ? "Mosaic unchanged" : "Mosaic changed"}</span>}
        <code data-testid="build" className="sr-only">
          {build}
        </code>
      </Button>
    </Tooltip>
  );
}

type ThemeChoice = "system" | "light" | "dark";
const THEME_KEY = "mosaic-theme";
const NEXT: Record<ThemeChoice, ThemeChoice> = { system: "light", light: "dark", dark: "system" };

function readTheme(): ThemeChoice {
  try {
    const v = localStorage.getItem(THEME_KEY);
    return v === "light" || v === "dark" ? v : "system";
  } catch {
    return "system";
  }
}

/** System, light or dark. Sets data-theme on <html>; "system" removes it and follows the OS. */
function ThemeSwitch() {
  const [theme, setTheme] = useState<ThemeChoice>(readTheme);
  useEffect(() => {
    const root = document.documentElement;
    if (theme === "system") delete root.dataset.theme;
    else root.dataset.theme = theme;
    try {
      if (theme === "system") localStorage.removeItem(THEME_KEY);
      else localStorage.setItem(THEME_KEY, theme);
    } catch {}
  }, [theme]);
  const icon = theme === "light" ? <SunIcon /> : theme === "dark" ? <MoonIcon /> : <CircleHalfIcon />;
  return <Button variant="tertiary" size="sm" icon={icon} aria-label={`Theme: ${theme}. Switch to ${NEXT[theme]}`} title={`Theme: ${theme}`} onClick={() => setTheme(NEXT[theme])} />;
}

/**
 * The mark: four tiles in a pinwheel around an empty square. The tiles are sites; the square is the
 * missing piece, Mosaic itself, and it drops into place once a site is connected.
 */
function MosaicMark({ complete }: { complete: boolean }) {
  return (
    <svg width="22" height="22" viewBox="0 0 30 30" aria-hidden="true" className={`mark ${complete ? "complete" : ""}`}>
      <rect className="t1" x="0" y="0" width="19" height="8" rx="2.5" />
      <rect className="t2" x="22" y="0" width="8" height="19" rx="2.5" />
      <rect className="t3" x="11" y="22" width="19" height="8" rx="2.5" />
      <rect className="t4" x="0" y="11" width="8" height="19" rx="2.5" />
      <rect className="slot" x="11.75" y="11.75" width="6.5" height="6.5" rx="1.75" />
      <rect className="piece" x="11" y="11" width="8" height="8" rx="2.5" />
    </svg>
  );
}

createRoot(document.getElementById("root")!).render(<App />);
